const CONFIG = {
    batteryCapacityKwh: 27,
    fallbackReservePct: 20,
    dischargeThresholdW: 100,
    sampleWindowMs: 10 * 60 * 1000,
    stateTopic: "nodered/powerwall_reserve/state",
    batteryEntity: "sensor.powerwalls_average",
    powerOutEntity: "sensor.tesla_powerwall_3_pw3_total_power_out",
    reserveEntity: "sensor.powerwall_backup_reserve"
};

function toNumber(value) {
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
}

function round(value, places = 2) {
    if (!Number.isFinite(value)) return null;
    const factor = Math.pow(10, places);
    return Math.round((value + Number.EPSILON) * factor) / factor;
}

function fmtMinutes(minutes) {
    if (!Number.isFinite(minutes)) return "";
    const total = Math.max(0, Math.round(minutes));
    const h = Math.floor(total / 60);
    const m = total % 60;
    if (h && m) return h + "h " + m + "m";
    if (h) return h + "h";
    return m + "m";
}

function makeConfigMessages(stateTopic) {
    const device = {
        identifiers: ["nodered_powerwall_reserve"],
        name: "Powerwall Reserve Forecast",
        manufacturer: "Node-RED",
        model: "Home Assistant + MQTT"
    };
    const sensors = [
        {
            key: "time_to_reserve_minutes",
            name: "Powerwall Time To Reserve",
            unit: "min",
            icon: "mdi:battery-clock-outline",
            device_class: "duration",
            state_class: "measurement",
            template: "{{ value_json.time_to_reserve_minutes }}"
        },
        {
            key: "time_to_reserve_text",
            name: "Powerwall Time To Reserve Text",
            icon: "mdi:clock-outline",
            template: "{{ value_json.time_to_reserve_text }}"
        },
        {
            key: "reserve_eta",
            name: "Powerwall Reserve ETA",
            icon: "mdi:calendar-clock",
            device_class: "timestamp",
            template: "{{ value_json.reserve_eta }}"
        },
        {
            key: "avg_discharge_power_10m",
            name: "Powerwall Avg Discharge Power 10m",
            unit: "W",
            icon: "mdi:transmission-tower-export",
            device_class: "power",
            state_class: "measurement",
            template: "{{ value_json.avg_discharge_power_10m }}"
        },
        {
            key: "usable_energy_to_reserve",
            name: "Powerwall Energy To Reserve",
            unit: "kWh",
            icon: "mdi:battery-arrow-down-outline",
            device_class: "energy",
            state_class: "measurement",
            template: "{{ value_json.usable_energy_to_reserve }}"
        }
    ];

    return sensors.map(function(sensor) {
        const payload = {
            unique_id: "nodered_powerwall_reserve_" + sensor.key,
            object_id: "powerwall_" + sensor.key,
            device: device,
            name: sensor.name,
            state_topic: stateTopic,
            value_template: sensor.template,
            icon: sensor.icon,
            json_attributes_topic: stateTopic,
            availability_topic: stateTopic,
            availability_template: "{% if value_json.available %}online{% else %}offline{% endif %}",
            payload_available: "online",
            payload_not_available: "offline"
        };
        if (sensor.unit) payload.unit_of_measurement = sensor.unit;
        if (sensor.device_class) payload.device_class = sensor.device_class;
        if (sensor.state_class) payload.state_class = sensor.state_class;
        return {
            topic: "homeassistant/sensor/powerwall_reserve/" + sensor.key + "/config",
            payload: JSON.stringify(payload),
            retain: true
        };
    });
}

const nowMs = Date.now();
const batteryPct = toNumber(msg.batteryPct);
const instantPowerW = toNumber(msg.powerOutW);
const actualReservePct = toNumber(msg.reservePct);
const reservePct = actualReservePct === null ? CONFIG.fallbackReservePct : actualReservePct;
let samples = flow.get("powerwallReserveSamples") || [];

if (instantPowerW !== null) {
    samples.push({ t: nowMs, w: Math.max(0, instantPowerW) });
}
samples = samples.filter(function(sample) {
    return sample && Number.isFinite(sample.t) && Number.isFinite(sample.w) && nowMs - sample.t <= CONFIG.sampleWindowMs;
});
flow.set("powerwallReserveSamples", samples);

const avgPowerW = samples.length ? samples.reduce((sum, sample) => sum + sample.w, 0) / samples.length : null;
const discharging = avgPowerW !== null && avgPowerW > CONFIG.dischargeThresholdW;
const usableKwh = batteryPct === null ? null : Math.max(0, (batteryPct - reservePct) / 100 * CONFIG.batteryCapacityKwh);
const minutes = discharging && usableKwh !== null && usableKwh > 0 ? (usableKwh / (avgPowerW / 1000)) * 60 : null;
const reserveEta = minutes === null ? null : new Date(nowMs + minutes * 60000).toISOString();

const payload = {
    available: batteryPct !== null && avgPowerW !== null,
    battery_percent: round(batteryPct, 1),
    instant_power_out_w: round(instantPowerW, 0),
    avg_discharge_power_10m: round(avgPowerW, 0),
    sample_count_10m: samples.length,
    discharging: discharging,
    battery_capacity_kwh: CONFIG.batteryCapacityKwh,
    reserve_percent: reservePct,
    reserve_percent_source: actualReservePct === null ? "fallback" : "sensor",
    usable_energy_to_reserve: round(usableKwh, 2),
    time_to_reserve_minutes: minutes === null ? null : Math.round(minutes),
    time_to_reserve_text: minutes === null ? "" : fmtMinutes(minutes),
    reserve_eta: reserveEta,
    source_battery_entity: CONFIG.batteryEntity,
    source_power_entity: CONFIG.powerOutEntity,
    source_reserve_entity: CONFIG.reserveEntity,
    updated_at: new Date(nowMs).toISOString()
};

const state = flow.get("powerwallReserveState") || {};
const configMessages = (msg.topic === "init" || !state.configPublished) ? makeConfigMessages(CONFIG.stateTopic) : null;
state.configPublished = true;
state.lastPayload = payload;
flow.set("powerwallReserveState", state);

return [configMessages, [{ topic: CONFIG.stateTopic, payload: JSON.stringify(payload), retain: true }], { topic: "powerwall_reserve", payload }];
